import 'package:flutter/material.dart';

class PPh {
  final String ru, en, tk, tr;
  const PPh(this.ru, this.en, this.tk, this.tr);
}

class PSub {
  final IconData icon;
  final String ru, en, tk, tr;
  final List<PPh> p;
  const PSub(this.icon, this.ru, this.en, this.tk, this.tr, this.p);
}

class PCat {
  final IconData icon;
  final String ru, en, tk, tr;
  final List<PSub> s;
  const PCat(this.icon, this.ru, this.en, this.tk, this.tr, this.s);
}

String phText(PPh p, String s) => switch (s) {
  'ru' => p.ru,
  'tk' => p.tk,
  'en' => p.en,
  'tr' => p.tr,
  _ => p.en,
};

String subText(PSub p, String s) => switch (s) {
  'ru' => p.ru,
  'tk' => p.tk,
  'en' => p.en,
  'tr' => p.tr,
  _ => p.en,
};

String catText(PCat p, String s) => switch (s) {
  'ru' => p.ru,
  'tk' => p.tk,
  'en' => p.en,
  'tr' => p.tr,
  _ => p.en,
};

int subCount(PSub s) => s.p.length;
int catCount(PCat c) => c.s.fold<int>(0, (a, s) => a + s.p.length);

